window.docContents[227].resolve({"/Bound-variables___-lambdas___-quantifiers___-define-fun/#Cvc___lean----High-Level-API-for-CVC5--Bound-variables___-lambdas___-quantifiers___-define-fun--Quantifiers":{"contents":"Unlike lambdas, quantifier terms simply have sort Bool which makes typing much easier.\n\nUniversal quantification of body over bvs.\n\nExistential quantification of body over bvs.\n\nHere is an example of building quantified terms by hand, smt! version below.\n\n#eval Env.runIO do\n  let n ← Term.mkSymbolAs Int \"n\"\n  let i ← Term.mkBVar \"i\"\n  let j ← Term.mkBVar \"j\"\n  let bVars_j := BVars.empty.push j\n  let all_le ← Term.mkForall bVars_j (← smt! n < j → i < j)\n  let bVars_i := BVars.empty.push i\n  let exists_i ← Term.mkExists bVars_i all_le\n  println! \"exists_i := {exists_i}\"\n\n  let solver ← Solver.new\n  solver.setOpt .smt_produceModels true\n  solver.assert exists_i\n  solver.checkSat (ifSat := do\n    println! \"sat\"\n    println! \"- n := {← n.getValue}\"\n  )\n\n\nexists_i := (exists ((i Int)) (forall ((j Int)) (=> (< n j) (< i j))))\nsat\n- n := -1\n\n\nWith the smt! extension:\n\n#eval Env.runIO do\n  let n ← Term.mkSymbolAs Int \"n\"\n  let exists_i ← smt!\n    ∃ (i : Int), ∀ (j : Int), n < j → i < j\n  println! \"exists_i := {exists_i}\"\n\n  let solver ← Solver.new\n  solver.setOpt .smt_produceModels true\n  solver.assert exists_i\n  solver.checkSat (ifSat := do\n    println! \"sat\"\n    println! \"- n := {← n.getValue}\"\n  )\n\n\nexists_i := (exists ((i Int)) (forall ((j Int)) (=> (< n j) (< i j))))\nsat\n- n := -1\n\n\n","context":"Cvc.lean -- High-Level API for CVC5\u0009Bound variables: lambdas, quantifiers, define-fun","header":"7.2. Quantifiers","id":"/Bound-variables___-lambdas___-quantifiers___-define-fun/#Cvc___lean----High-Level-API-for-CVC5--Bound-variables___-lambdas___-quantifiers___-define-fun--Quantifiers"}});